engine.activityValidate:
function activityValidate(entry) {
  var SCHEMA = window.eli.activity && window.eli.activity.SCHEMA;
  if (!SCHEMA) return null;
  if (!entry || typeof entry !== "object") return "entry must be an object";
  var keys = Object.keys(SCHEMA);
  for (var i = 0; i < keys.length; i++) {
    var key = keys[i];
    var spec = SCHEMA[key];
    var v = entry[key];
    if (spec.required && (v == null || v === "")) {
      return "missing required field: " + key;
    }
    if (v != null && typeof v !== spec.type) {
      return "field '" + key + "' should be " + spec.type + ", got " + typeof v;
    }
  }
  return null;
}

engine.activityAgo:
function activityAgo(ts) {
  if (!ts) return "";
  var sec = Math.floor((Date.now() - ts) / 1000);
  if (sec < 5) return "just now";
  if (sec < 60) return sec + "s";
  if (sec < 3600) return Math.floor(sec / 60) + "m";
  if (sec < 86400) return Math.floor(sec / 3600) + "h";
  return Math.floor(sec / 86400) + "d";
}

view.renderActivity:
function renderActivity(opts) {
  var panel = document.createElement("div");
  panel.className = "feed-container";
  panel.id = "_eli3_activity_panel";
  var head = document.createElement("div");
  head.className = "feed-header";
  head.innerHTML =
    '<div class="feed-header-left">' +
      '<button type="button" class="feed-collapse-toggle" id="_eli3_activity_collapse" title="Collapse / expand session feed" aria-expanded="true">▾</button>' +
      '<span class="feed-header-icon">⚡</span>' +
      '<span class="feed-header-title">ELI SESSION FEED</span>' +
    '</div>' +
    // Center slot — empty by default. Other tools (oars_loader paints
    // the "Copy Filename" button here when OARS data is attached) hook
    // in via the eli_activity:header_mounted bus event.
    '<div class="feed-header-center" id="_eli3_activity_header_center"></div>' +
    '<div class="feed-header-count" id="_eli3_activity_count">0</div>';
  panel.appendChild(head);
  // Bus emit — additive: when no listener is installed, the slot stays
  // empty and the header looks identical to before this change.
  try {
    if (window.eli && window.eli.bus && typeof window.eli.bus.emit === "function") {
      var slotEl = head.querySelector("#_eli3_activity_header_center");
      window.eli.bus.emit("eli_activity:header_mounted", { slotEl: slotEl });
    }
  } catch (_e) {}
  var list = document.createElement("div");
  list.className = "feed-list";
  list.id = "_eli3_activity_rail";
  panel.appendChild(list);

  // ─── Collapse / expand wiring + initial-state from settings ────
  // Reads `minimizeFeed` from eli_user_settings (set via Settings →
  // Interface → 📌 Minimize Session Feed on Start). When true, the
  // feed renders with the list hidden + chevron pointing right. Click
  // header / chevron to toggle during session; state persists back to
  // the same setting key so it survives reload.
  // 2026-05-18 v52: read FRESH on each persist write. The previous
  // code captured the settings blob into a `_userSettings` closure at
  // first render, then wrote that stale blob on every feed collapse/
  // expand — silently clobbering ANY other setting key the user
  // changed after boot (autoHideSidebar, lightMode, expandWidth,
  // showExpandPill, modelList, fileNamePatterns, etc.). The classic
  // symptom: user toggles Auto-Hide Sidebar on → collapses the feed
  // → autoHideSidebar reverts to its boot value.
  function _readUserSettingsFresh() {
    try {
      var raw = window.eli && window.eli.compat && typeof window.eli.compat.lsGet === "function"
        ? window.eli.compat.lsGet("eli_user_settings")
        : (window.localStorage && window.localStorage.getItem("eli_user_settings"));
      return raw ? (JSON.parse(raw) || {}) : {};
    } catch (_e) { return {}; }
  }
  var _initiallyMinimized = !!_readUserSettingsFresh().minimizeFeed;
  var collapseBtn = head.querySelector("#_eli3_activity_collapse");
  function _applyCollapsedState(collapsed) {
    if (collapsed) {
      panel.classList.add("feed-collapsed");
      list.style.display = "none";
      if (collapseBtn) { collapseBtn.textContent = "▸"; collapseBtn.setAttribute("aria-expanded", "false"); }
    } else {
      panel.classList.remove("feed-collapsed");
      list.style.display = "";
      if (collapseBtn) { collapseBtn.textContent = "▾"; collapseBtn.setAttribute("aria-expanded", "true"); }
    }
  }
  function _toggleCollapsed() {
    var nowCollapsed = !panel.classList.contains("feed-collapsed");
    _applyCollapsedState(nowCollapsed);
    // Persist back to user settings so the choice carries across reloads.
    // Read-merge-write the FRESH blob so we only mutate minimizeFeed and
    // leave every other key untouched.
    try {
      var fresh = _readUserSettingsFresh();
      fresh.minimizeFeed = nowCollapsed;
      var payload = JSON.stringify(fresh);
      if (window.eli && window.eli.compat && typeof window.eli.compat.lsSet === "function") {
        window.eli.compat.lsSet("eli_user_settings", payload);
      } else if (window.localStorage) {
        window.localStorage.setItem("eli_user_settings", payload);
      }
    } catch (_e) {}
  }
  if (collapseBtn) collapseBtn.onclick = function (ev) {
    ev.stopPropagation();
    _toggleCollapsed();
  };
  // Click the header (anywhere not in the center slot or the count)
  // also toggles — bigger click target than the small chevron.
  head.onclick = function (ev) {
    // Ignore clicks inside the center slot (so the OARS Copy Filename
    // button + future header buttons don't trigger a collapse).
    var center = head.querySelector(".feed-header-center");
    if (center && center.contains(ev.target)) return;
    if (ev.target === collapseBtn) return; // chevron has its own handler
    _toggleCollapsed();
  };
  if (_initiallyMinimized) _applyCollapsedState(true);

  // Inline helpers — bundle isolation prevents inter-fn calls, so each
  // top-level view fn defines its own. Mirrors the kernel's prior
  // closure-scoped helpers; functionally identical to the inline copies
  // in refreshActivity.
  function _appendItem(listEl, e) {
    var ago = (typeof opts.ago === "function") ? opts.ago : function (ts) { return ts ? String(ts) : ""; };
    var dispatch = opts.dispatch;
    var toast = opts.toast;
    var item = document.createElement("div");
    item.className = "feed-item";
    var label = e.label || e.type || "Event";
    var summary = e.summary || "";
    // 2026-05-13 follow-up: accept BOTH restore shapes.
    //   1. `restoreChannel` + `restoreKey` — dispatch-based, survives
    //      kernel reload (handler looked up from registry at click time).
    //   2. `restoreFn` — in-memory closure on the entry, same-session
    //      only (functions don't survive IDB serialization). Used by
    //      review_redlines so each scan restores to its exact session
    //      snapshot without having to round-trip the payload through
    //      a registered handler.
    var hasDispatchRestore = !!(e.payload && e.restoreChannel && e.restoreKey);
    var hasFnRestore = typeof e.restoreFn === "function";
    var canRestore = hasDispatchRestore || hasFnRestore;
    if (canRestore) {
      item.classList.add("restorable");
      item.title = label + (summary ? " — " + summary : "") + " (" + ago(e.timestamp) + ") — click to restore";
      item.style.cursor = "pointer";
      item.onclick = function () {
        try {
          // 2026-06-04: emit tool:open so subscribers (ask_dock chevron's
          // allowlist gate, future tool-presence listeners) know which
          // tool is now active. Resolve the OWNER tool id via findOwner
          // — restoreKey isn't necessarily the tool id (e.g. review_redlines
          // uses restoreKey: "review-redline" while its tool id is
          // "review_redlines"). Fall back to restoreKey if no owner found.
          try {
            var _ownerForEmit = (typeof opts.findOwner === "function")
              ? opts.findOwner(e.restoreChannel, e.restoreKey)
              : null;
            if (window.eli && window.eli.bus && typeof window.eli.bus.emit === "function") {
              window.eli.bus.emit("tool:open", {
                id: _ownerForEmit || e.restoreKey,
                via: "activity_restore",
              });
            }
          } catch (_ev) {}
          if (hasFnRestore) { e.restoreFn(e.payload); return; }
          var handler = (typeof dispatch === "function") ? dispatch(e.restoreChannel, e.restoreKey) : null;
          if (typeof handler === "function") { handler(e.payload); return; }
          // 2026-05-16: late-load fallback. Handler not registered yet —
          // the owning tool is preload/demand and hasn't eval'd. Find
          // the tool that advertises this channel/key, ensureLoaded it,
          // then re-resolve and fire. Removes the "must be boot tier"
          // constraint for tools that register activity_restore handlers.
          var findOwner = opts.findOwner;
          var ensureLoaded = opts.ensureLoaded;
          var ownerId = (typeof findOwner === "function") ? findOwner(e.restoreChannel, e.restoreKey) : null;
          if (!ownerId || typeof ensureLoaded !== "function") {
            if (typeof toast === "function") toast("This activity can't be restored (handler missing).", "warn");
            return;
          }
          ensureLoaded(ownerId).then(function () {
            var h2 = dispatch(e.restoreChannel, e.restoreKey);
            if (typeof h2 === "function") { h2(e.payload); return; }
            if (typeof toast === "function") toast("Tool loaded but handler still missing.", "warn");
          }).catch(function (err2) {
            if (typeof toast === "function") toast("Couldn't load tool for restore: " + (err2 && err2.message || "unknown"), "err");
          });
        } catch (err) {
          if (typeof toast === "function") toast("Restore failed: " + (err && err.message || "unknown"), "err");
        }
      };
    } else {
      item.title = label + (summary ? " — " + summary : "") + " (" + ago(e.timestamp) + ")";
    }
    var icon = document.createElement("div");
    icon.className = "feed-icon";
    icon.textContent = e.icon || "•";
    item.appendChild(icon);
    var body = document.createElement("div");
    body.className = "feed-body";
    var lbl = document.createElement("div");
    lbl.className = "feed-label";
    lbl.textContent = label;
    body.appendChild(lbl);
    if (summary) {
      var sm = document.createElement("div");
      sm.className = "feed-summary";
      sm.textContent = summary;
      body.appendChild(sm);
    }
    item.appendChild(body);
    var meta = document.createElement("div");
    meta.className = "feed-meta";
    var time = document.createElement("div");
    time.className = "feed-time";
    time.textContent = ago(e.timestamp);
    meta.appendChild(time);
    if (canRestore) {
      var restore = document.createElement("div");
      restore.className = "feed-restore";
      restore.textContent = "↺ RESTORE";
      meta.appendChild(restore);
    }
    item.appendChild(meta);
    listEl.appendChild(item);
  }

  function _populate(listEl) {
    listEl.innerHTML = "";
    // 2026-06-13: show the whole session ring (cap 200) so you can scroll
    // back through every tool used, not just the last 30. Rail scrolls
    // horizontally; newest stays rightmost (auto-scroll below).
    var entries = (typeof opts.list === "function") ? opts.list({ limit: 200 }) : [];
    var panelEl = listEl.closest(".feed-container") || listEl.parentNode;
    var countEl = panelEl ? panelEl.querySelector(".feed-header-count") : null;
    if (countEl) countEl.textContent = entries.length;
    if (!entries.length) {
      var empty = document.createElement("div");
      empty.className = "_eli3_activity_empty";
      empty.textContent = "No activity yet.";
      listEl.appendChild(empty);
      return;
    }
    entries.forEach(function (e, idx) {
      if (idx > 0) {
        var arrow = document.createElement("div");
        arrow.className = "feed-arrow";
        arrow.textContent = "➔";
        listEl.appendChild(arrow);
      }
      _appendItem(listEl, e);
    });
    setTimeout(function () { listEl.scrollLeft = listEl.scrollWidth; }, 0);
  }

  _populate(list);
  return panel;
}


