jsonTools.init:
function init(eli) {
  if (!eli.events) eli.events = { guard: function (fn) { return fn; }, safeAsync: function (p) { return p; } };
  var bundle = eli.tools._loaded["eli-activity"];
  if (!bundle) return;

  // ─── Install real eli.log provider (kernel had only a stub) ──────────
  // 2026-05-12 offload: ring buffer + autoSubscribe + exportJSON +
  // copyToClipboard moved here from kernel §13.5. Stub drained.
  _installRealLogProvider(eli);
  function _installRealLogProvider(eli) {
    var MAX_EVENTS = 200;
    var _ring = [];
    // Drain stub's ring so we don't lose boot-self-test events.
    if (window.eli.log && typeof window.eli.log._drainRing === "function") {
      try { _ring = window.eli.log._drainRing().slice(0, MAX_EVENTS); } catch (_) {}
    }
    var _subscribers = [];
    var _autoSubscribed = false;
    function _sanitizeValue(v) {
      if (v == null) return v;
      if (typeof v === "string") {
        return (window.eli.ai && window.eli.ai.sanitizePII)
          ? window.eli.ai.sanitizePII(v)
          : v;
      }
      if (typeof v !== "object") return v;
      if (Array.isArray(v)) return v.map(_sanitizeValue);
      var out = {};
      Object.keys(v).forEach(function (k) { out[k] = _sanitizeValue(v[k]); });
      return out;
    }
    function event(channel, name, payload, opts) {
      opts = opts || {};
      var entry = {
        channel: String(channel || "kernel"),
        name: String(name || ""),
        payload: opts.sanitize === false ? payload : _sanitizeValue(payload),
        timestamp: Date.now(),
        sanitized: opts.sanitize !== false,
      };
      _ring.push(entry);
      while (_ring.length > MAX_EVENTS) _ring.shift();
      _subscribers.slice().forEach(function (cb) {
        try { cb(entry); } catch (_) {}
      });
      return entry;
    }
    function list(opts) {
      opts = opts || {};
      var out = _ring;
      if (opts.channel) out = out.filter(function (e) { return e.channel === opts.channel; });
      if (opts.limit) out = out.slice(-opts.limit);
      return out.slice();
    }
    function clear() { _ring = []; }
    function exportJSON() {
      return {
        kernelVersion: window.eli.kernelVersion,
        exportedAt: new Date().toISOString(),
        eventCount: _ring.length,
        events: _ring.slice(),
      };
    }
    function subscribe(cb) {
      if (typeof cb !== "function") return function () {};
      _subscribers.push(cb);
      return function () {
        var i = _subscribers.indexOf(cb);
        if (i !== -1) _subscribers.splice(i, 1);
      };
    }
    function autoSubscribe() {
      if (_autoSubscribed) return;
      if (!window.eli.bus) return;
      _autoSubscribed = true;
      window.eli.bus.on("fsm:transition",        function (p) { event("fsm", "transition", p); });
      window.eli.bus.on("ai:request_started",    function (p) { event("ai",  "request_started", p); });
      window.eli.bus.on("ai:request_finished",   function (p) { event("ai",  "request_finished", p); });
      window.eli.bus.on("activity:added",        function (p) { event("activity", "added", { type: p && p.type, label: p && p.label, summary: p && p.summary }); });
      window.eli.bus.on("tool:installed",        function (p) { event("tool", "installed", p); });
      window.eli.bus.on("tool:uninstalled",      function (p) { event("tool", "uninstalled", p); });
      window.eli.bus.on("runtime:error",         function (p) { event("runtime", "error", p); });
      window.eli.bus.on("doc:dirty",             function (p) { event("doc", "dirty", p); });
      window.eli.bus.on("manifest:fetched",      function (p) { event("manifest", "fetched", p); });
    }
    function copyToClipboard() {
      var json = JSON.stringify(exportJSON(), null, 2);
      if (typeof window._eliClipboardWriteOrFallback === "function") {
        return window._eliClipboardWriteOrFallback(json, "ELI Log Buffer (" + _ring.length + " events)");
      }
      // Last-resort fallback if the kernel helper isn't around.
      try { if (navigator.clipboard) return navigator.clipboard.writeText(json); } catch (_) {}
      return Promise.resolve();
    }
    window.eli.log = {
      event: event, list: list, clear: clear,
      exportJSON: exportJSON, copyToClipboard: copyToClipboard,
      subscribe: subscribe, autoSubscribe: autoSubscribe,
      MAX_EVENTS: MAX_EVENTS,
    };
    autoSubscribe();
  }
  var efns = bundle._eliEngineFns || {};
  var vfns = bundle._eliViewFns || {};
  var validate = efns.activityValidate;
  var ago = efns.activityAgo;
  var renderActivity = vfns.renderActivity;
  var refreshActivity = vfns.refreshActivity;
  if (!validate || !ago || !renderActivity || !refreshActivity) {
    eli.log.event("tool", "eli_activity_load_failed", {
      hasValidate: !!validate, hasAgo: !!ago,
      hasRenderActivity: !!renderActivity, hasRefreshActivity: !!refreshActivity,
    });
    return;
  }

  // ─── Storage-backed ring (replaces kernel §13 IIFE) ──────────────
  var STORE_CONFIG = "config";
  var ACTIVITY_KEY = "activity_feed";
  var MAX_ENTRIES = 200;
  var PERSIST_DEBOUNCE_MS = 1000;

  // Migrate whatever the kernel stub buffered before we evaluated.
  // The stub stores its in-memory ring on window.eli.activity._stubRing.
  var _ring = (window.eli.activity && Array.isArray(window.eli.activity._stubRing))
    ? window.eli.activity._stubRing.slice()
    : [];
  var _persistTimer = null;
  var _hydrated = false;

  function _schedulePersist() {
    if (_persistTimer) return;
    _persistTimer = setTimeout(function () {
      _persistTimer = null;
      _persist();
    }, PERSIST_DEBOUNCE_MS);
  }
  // 2026-05-23: persist ONLY download entries (type prefix "download.").
  // Activity feed visible UI is session-only (in-memory ring); cross-
  // session persistence is scoped to downloads. doc_loaded, scan completions,
  // tool launches, etc. live and die with each session. Downloads (tools,
  // templates, data libraries) accumulate in a bounded IDB ring so admin
  // tools / future "What was downloaded recently?" views have history.
  //
  // Read-merge-write: read IDB, merge unseen download entries from
  // current ring, cap at MAX_ENTRIES (FIFO), strip payload, write back.
  // Non-download entries are never written.
  function _isDownloadEntry(e) {
    return e && typeof e.type === "string" && e.type.indexOf("download") === 0;
  }
  function _persist() {
    var ringDownloads = _ring.filter(_isDownloadEntry);
    // No downloads happened this session — skip the IDB round-trip entirely.
    if (!ringDownloads.length) return Promise.resolve();
    return eli.storage.get(STORE_CONFIG, ACTIVITY_KEY)
      .catch(function () { return null; })
      .then(function (existing) {
        var bySeenId = {};
        ringDownloads.forEach(function (e) { if (e && e.id) bySeenId[e.id] = true; });
        var past = (existing && Array.isArray(existing.entries)) ? existing.entries : [];
        // Past entries: keep only ones that are still download entries
        // (defensive — if the policy changes in future we don't carry junk).
        // Drop any current-ring duplicates by id.
        var pastFiltered = past.filter(function (e) {
          return _isDownloadEntry(e) && !(e && e.id && bySeenId[e.id]);
        });
        var merged = pastFiltered.concat(ringDownloads).slice(-MAX_ENTRIES);
        // Slim shape — strip payload before write.
        var slim = merged.map(function (e) {
          if (!e || typeof e !== "object") return e;
          var out = {};
          for (var k in e) {
            if (e.hasOwnProperty(k) && k !== "payload") out[k] = e[k];
          }
          return out;
        });
        return eli.storage.put(STORE_CONFIG, {
          key: ACTIVITY_KEY,
          entries: slim,
          updatedAt: Date.now(),
        });
      }).catch(function () { /* tolerate */ });
  }

  function add(entry) {
    if (entry && typeof entry === "object") {
      if (!entry.timestamp) entry.timestamp = Date.now();
      if (!entry.id) entry.id = "act_" + entry.timestamp + "_" + Math.random().toString(36).slice(2, 8);
    }
    var err = validate(entry);
    if (err) {
      throw new eli.errors.ValidationError("activity.add: " + err, { meta: { entry: entry } });
    }
    _ring.push(entry);
    while (_ring.length > MAX_ENTRIES) _ring.shift();
    _schedulePersist();
    try { eli.bus.emit("activity:added", entry); } catch (e) { /* noop */ }
    return entry;
  }

  var _RESERVED_UPDATE_KEYS = { id: true, timestamp: true };
  function update(id, patch) {
    if (!id || !patch || typeof patch !== "object") return null;
    for (var i = _ring.length - 1; i >= 0; i--) {
      var e = _ring[i];
      if (e && e.id === id) {
        Object.keys(patch).forEach(function (k) {
          if (_RESERVED_UPDATE_KEYS[k]) return;
          e[k] = patch[k];
        });
        e.updatedAt = Date.now();
        var err = validate(e);
        if (err) {
          throw new eli.errors.ValidationError(
            "activity.update: patch produced invalid entry: " + err,
            { meta: { id: id, patch: patch } }
          );
        }
        _schedulePersist();
        try { eli.bus.emit("activity:updated", e); } catch (busErr) { /* noop */ }
        return e;
      }
    }
    return null;
  }

  // 2026-05-23: filter download entries out of the visible session feed.
  // Downloads still live in the ring (so _persist writes them to IDB) and
  // still show in the ELI AI dialog's Downloads tab. They just don't
  // belong on the user-facing session feed — the session feed is for
  // "what just happened in this session" (doc loaded, scans completed,
  // tool launches), and downloads are infra noise.
  // Opt-in `includeInternal` (used by debug surfaces) and a new
  // `includeDownloads` flag let consumers see them when they need to.
  function list(opts) {
    opts = opts || {};
    var src = opts.includeInternal
      ? _ring
      : _ring.filter(function (e) {
          return !(e && typeof e.type === "string" && e.type.charAt(0) === "_");
        });
    if (!opts.includeDownloads) {
      src = src.filter(function (e) {
        return !(e && typeof e.type === "string" && e.type.indexOf("download") === 0);
      });
    }
    var limit = opts.limit ? Math.min(opts.limit, src.length) : src.length;
    return src.slice(-limit);
  }

  function clear() {
    _ring = [];
    if (_persistTimer) { clearTimeout(_persistTimer); _persistTimer = null; }
    return eli.storage.delete(STORE_CONFIG, ACTIVITY_KEY).catch(function () { /* tolerate */ });
  }

  function hydrate() {
    return eli.storage.get(STORE_CONFIG, ACTIVITY_KEY).then(function (row) {
      if (row && Array.isArray(row.entries)) {
        // Merge: persisted ring + any in-memory entries from the stub.
        // Dedup by id; the stub-buffered entries always win (most recent).
        var bySeenId = {};
        _ring.forEach(function (e) { if (e && e.id) bySeenId[e.id] = true; });
        var merged = row.entries.filter(function (e) { return !(e && e.id && bySeenId[e.id]); });
        _ring = merged.concat(_ring).slice(-MAX_ENTRIES);
      }
      _hydrated = true;
      return _ring.length;
    }).catch(function () { _hydrated = true; return 0; });
  }

  // Overwrite the kernel stub with the real implementation. SCHEMA stays
  // kernel-side (eli.activity.SCHEMA) — only behavior moves.
  eli.activity.add = add;
  eli.activity.update = update;
  eli.activity.list = list;
  eli.activity.clear = clear;
  eli.activity.hydrate = hydrate;
  eli.activity.isHydrated = function () { return _hydrated; };
  eli.activity.MAX_ENTRIES = MAX_ENTRIES;
  // Cleanup the stub's buffer reference — we've drained it into _ring.
  try { delete eli.activity._stubRing; } catch (e) {}

  // ─── Bus → activity translators ──────────────────────────────────
  // 2026-05-23: subscribe to kernel install/update bus events and emit
  // properly-typed download entries. Without these, tool/library installs
  // happen silently and the Downloads tab (in ELI AI dialog) stays empty
  // even after auto-updates. Type prefix "download." gets the entry
  // persisted across sessions via the _isDownloadEntry filter above.
  if (eli.bus && typeof eli.bus.on === "function") {
    eli.bus.on("tool:installed", function (payload) {
      try {
        var id = payload && payload.id;
        if (!id) return;
        // De-dupe by id+version so re-install of the same exact version
        // doesn't spam the feed. Different versions → distinct entries
        // (so the timeline shows updates).
        var version = (payload && payload.version) || "";
        var entryId = "download.tool." + id + "@" + version + ":" + Date.now();
        add({
          id: entryId,
          type: "download.tool",
          icon: "📦",
          label: id + (version ? " v" + version : ""),
          summary: "Tool installed/updated",
          timestamp: Date.now(),
        });
      } catch (_e) { /* tolerate */ }
    });
    // Data library installs — kernel emits `data:loaded` (not data:installed)
    // from the post-install hydration path at taskpane_v3.js:7106.
    // Payload shape: { id, sections: [<section_name>, ...] }
    eli.bus.on("data:loaded", function (payload) {
      try {
        var id = (payload && payload.id) || "(unknown)";
        var sections = (payload && Array.isArray(payload.sections)) ? payload.sections : [];
        var entryId = "download.data." + id + ":" + Date.now();
        add({
          id: entryId,
          type: "download.data",
          icon: "📚",
          label: id,
          summary: sections.length
            ? sections.length + " section" + (sections.length === 1 ? "" : "s") + ": " + sections.join(", ")
            : "Data library loaded",
          timestamp: Date.now(),
        });
      } catch (_e) { /* tolerate */ }
    });
  }

  // ─── Renderer slot + bus wiring ──────────────────────────────────
  function _renderOpts() {
    return {
      list: list,
      ago: ago,
      dispatch: function (channel, key) { return eli.get && eli.get(channel, key); },
      // 2026-05-16: enable late-load fallback for restore clicks. When a
      // user clicks an activity entry whose handler isn't registered yet
      // (because the owning tool is preload/demand and hasn't eval'd),
      // findOwner identifies the tool by scanning loaded bundles'
      // advertises blocks; ensureLoaded triggers the eval; the click
      // handler then re-resolves the dispatch and fires it. Removes
      // the "must be boot tier to make activity_restore work" constraint.
      findOwner: function (channel, key) {
        if (!eli.tools || !eli.tools._loaded) return null;
        var found = null;
        Object.keys(eli.tools._loaded).forEach(function (id) {
          var b = eli.tools._loaded[id];
          var adv = b && b.advertises;
          if (adv && adv[channel] && adv[channel][key]) found = id;
        });
        return found;
      },
      ensureLoaded: function (id) {
        return (eli.tools && typeof eli.tools.ensureLoaded === "function")
          ? eli.tools.ensureLoaded(id)
          : Promise.resolve(false);
      },
      toast: function (msg, kind) { if (typeof showToast === "function") showToast(msg, kind); },
    };
  }

  if (eli.dashboard && typeof eli.dashboard.registerHomeSlot === "function") {
    eli.dashboard.registerHomeSlot("activity_feed", function (opts) {
      // Kernel slot infra hands us a mount; we paint our panel into it.
      // `position: "below"` puts the slot in the after-tiles host
      // (_eli3_below_slots), preserving the prior visual position the
      // kernel-rendered feed had. Pre-Batch-7 kernels without the
      // position option fall back to "above" — visible position drift
      // for users on old kernels but no breakage.
      var mount = opts && opts.mount;
      if (!mount) return;
      mount.innerHTML = "";
      mount.appendChild(renderActivity(_renderOpts()));
    }, { order: 50, position: "below" });
  }

  // Refresh on add / update — the bus emit comes from add/update above
  // (and from any other code path that emits these events).
  if (eli.bus && typeof eli.bus.on === "function") {
    eli.bus.on("activity:added", function () { refreshActivity(_renderOpts()); });
    eli.bus.on("activity:updated", function () { refreshActivity(_renderOpts()); });
  }

  // 2026-05-22: cross-session persistence (storage layer) + session-scoped
  // rendering (UI layer). The persist() function does read-merge-write so
  // IDB carries history across sessions — admin tools can query it for
  // audit. But the rendered feed stays SESSION-SCOPED: hydrate() is NOT
  // called on boot, so the visible rail starts empty each kernel reload
  // and only this session's entries appear.
  //
  // 2026-05-23: the earlier auto-hydrate caused doc_loaded events (which
  // fire every boot) to accumulate visibly across sessions. Reverting to
  // session-scoped rendering preserves the user's expectation that "the
  // feed shows what I did THIS session" while keeping cross-session data
  // available for admin tools via `eli.activity.hydrate()` from console
  // or via direct IDB read.

  eli.log.event("tool", "eli_activity_initialized", { ringSize: _ring.length });
}

