/* tools/eli-activity/style.css
 * Activity feed (session feed) styles. Moved from taskpane_v3.css 1165-1351
 * in Batch 7 (2026-05-11). Includes the dark-mode default + the
 * light-mode (.beta-ui-active.light-mode) overrides + the empty-state
 * label. CSS variables (--bg-feed, --color-gold, --space-*, --font-*)
 * are kernel-defined in :root so this bundle inherits them.
 */

/* ─── §8  Activity feed (session feed)
 *   What: `.feed-container`, `.feed-header`, `.feed-list`, `.feed-item`,
 *         `.feed-arrow`, `.feed-icon`, `.feed-body`, `.feed-restore`.
 *   Who emits: kernel's _renderActivity.
 *   Modifier: `.feed-item.restorable` → click-to-restore.
 */
/* Push the activity feed to the bottom of the dashboard main column.
 * Pre-Batch-7 the kernel rendered .feed-container as a direct child of
 * _eli3_main, so `margin-top: auto` worked. After Batch 7 the slot
 * wrappers add two layers (_eli3_below_slots > _eli3_home_slot >
 * .feed-container), so push from the outermost wrapper instead. */
._eli3_below_slots {
  margin-top: auto;
  margin-bottom: var(--space-3);    /* 12px gap before footer */
  display: flex;
  flex-direction: column;
  /* min-width:0 down the whole chain so the chip rail's overflow-x:auto
   * actually scrolls instead of widening its ancestors. 2026-06-13. */
  min-width: 0;
}
._eli3_below_slots > ._eli3_home_slot {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

/* Feed container — no padding-bottom inside (dark bg ends right at the
 * chip rail). Outer push handled by ._eli3_below_slots above. */
.feed-container {
  flex: 0 0 auto;
  background: var(--bg-feed);
  border-top: 1px solid var(--border-subtle);
  padding-bottom: 0;
  min-width: 0;
}
/* Grid layout (changed from flex 2026-05-16): three equal columns
   guarantee the center slot's contents sit at TRUE center regardless
   of how wide the left or right regions get. Flex+justify-content:
   space-between only centers when left+right are equal-width. */
.feed-header {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  padding: 6px var(--space-3);
  background: var(--bg-feed-row-grad);
  border-bottom: 1px solid var(--border-subtle);
  cursor: pointer; /* click anywhere in header to toggle collapse */
}
/* Chevron collapse toggle — sits at the front of the header-left. */
.feed-collapse-toggle {
  background: transparent;
  border: none;
  color: var(--color-gold);
  font: 700 11px/1 'Inter', sans-serif;
  cursor: pointer;
  padding: 0 4px 0 0;
  width: 16px;
  text-align: center;
  transition: opacity 0.12s, transform 0.12s;
  opacity: 0.85;
}
.feed-collapse-toggle:hover {
  opacity: 1;
  transform: translateY(1px);
}
/* When the feed is collapsed, hide the bottom border on the header so
   it visually matches "this whole panel is closed." */
.feed-container.feed-collapsed .feed-header {
  border-bottom-color: transparent;
}
.feed-header-left {
  display: flex;
  align-items: center;
  gap: 6px;
  justify-self: start;
}
.feed-header-center {
  display: flex;
  align-items: center;
  justify-content: center;
  justify-self: center;
  min-width: 0;
}
.feed-header-icon { font-size: 12px; filter: drop-shadow(0 0 var(--space-1) rgba(201, 162, 39, 0.5)); }
.feed-header-title {
  font: var(--weight-bold) var(--font-xs)/1.3 var(--font-family);
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--color-gold);
}
/* Count pill — gold square with dark text. v2-exact. justify-self
   keeps it right-aligned in the grid's third column. */
.feed-header-count {
  justify-self: end;
  font: var(--weight-extrabold) var(--font-xs)/1.2 var(--font-family);
  color: #0d1b2a;
  background: var(--color-gold-warm);
  padding: 1px 7px;
  min-width: 16px;
  text-align: center;
}

.feed-list,
._eli3_activity_rail {
  display: flex;
  flex-direction: row;
  gap: 6px;
  padding: var(--space-1) 6px;   /* 4px 6px — v2-exact */
  max-width: 100%;
  min-width: 0;
  overflow-x: auto;
  overflow-y: hidden;
  /* Hide the horizontal scrollbar visually — chip rail still scrolls
   * (mouse wheel / trackpad / touch), it just doesn't display a bar.
   * User feedback 2026-05-11: the always-visible bar looked broken. */
  scrollbar-width: none;          /* Firefox */
  -ms-overflow-style: none;       /* old Edge / IE */
}
.feed-list::-webkit-scrollbar,
._eli3_activity_rail::-webkit-scrollbar {
  display: none;                  /* WebKit */
}
.feed-arrow {
  align-self: center;
  color: var(--color-gold);
  font-weight: var(--weight-extrabold);
  flex-shrink: 0;
  font-size: 12px;
}
/* Chip — symmetric padding top/bottom. `position: relative` so the
 * restore overlay (.feed-restore) anchors to this box. */
.feed-item {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  padding: var(--space-1) var(--space-2);
  border: 1px solid var(--border-subtle);
  background: var(--bg-overlay-soft);
  width: 96px;
  flex-shrink: 0;
  text-align: center;
  transition: background 0.15s, border-color 0.15s;
  overflow: hidden;
}
.feed-item:hover {
  background: var(--bg-overlay-soft-h);
  border-color: var(--border-subtle-h);
}
.feed-item.restorable { cursor: pointer; }
.feed-item.restorable:hover {
  border-color: rgba(201, 162, 39, 0.7);
  box-shadow: 0 2px 6px rgba(201, 162, 39, 0.15);
}
.feed-icon { font-size: 18px; }
.feed-body {
  display: flex;
  flex-direction: column;
  gap: 1px;
  width: 100%;
}
.feed-label {
  font: var(--weight-bold) var(--font-xs)/1.2 var(--font-family);
  letter-spacing: 0.4px;
  text-transform: uppercase;
  color: var(--color-gold);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.feed-summary {
  font: var(--weight-semibold) var(--font-xs)/1.2 var(--font-family);
  color: var(--text-muted);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  max-height: 22px;
}
.feed-meta { width: 100%; }
.feed-time {
  font: var(--weight-semibold) 8px/1 var(--font-family);
  color: var(--text-status-footer);
  text-align: center;
}
/* Restore label — full-chip overlay on hover. Gold background, dark
 * text. Hidden completely (display:none) when not hovered so it doesn't
 * reserve layout space inside the chip. */
.feed-restore {
  display: none;
  position: absolute;
  inset: 0;
  background: var(--color-gold-warm);
  color: #0d1b2a;
  font: var(--weight-extrabold) 10px/1 var(--font-family);
  letter-spacing: 0.8px;
  text-transform: uppercase;
  text-align: center;
  align-items: center;
  justify-content: center;
  z-index: 5;
}
.feed-item.restorable:hover .feed-restore { display: flex; }

._eli3_activity_empty {
  padding: 6px 10px;
  color: var(--text-status-footer);
  font-style: italic;
  font-size: var(--font-sm);
}

/* Feed light-mode overrides (v2-parity) */
body.light-mode.beta-ui-active .feed-container {
  background: linear-gradient(180deg, #ffffff 0%, #f6f8fb 100%) !important;
  border: 1px solid #c2cdd9 !important;
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.06), 0 1px 3px rgba(0, 0, 0, 0.04) !important;
}
body.light-mode.beta-ui-active .feed-header {
  background: linear-gradient(180deg, #edf1f7 0%, #e4eaf2 100%) !important;
  border-bottom: 1px solid #cdd6e1 !important;
}
body.light-mode.beta-ui-active .feed-header-title,
body.light-mode.beta-ui-active .feed-header-left {
  color: #334155 !important;
  text-shadow: none !important;
}
body.light-mode.beta-ui-active .feed-header-count {
  color: #334155 !important;
  background: #e2e8f0 !important;
}
body.light-mode.beta-ui-active .feed-list { background: transparent !important; }
body.light-mode.beta-ui-active .feed-item {
  background: linear-gradient(180deg, #ffffff 0%, #f6f8fb 100%) !important;
  border: 1px solid #c2cdd9 !important;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.04) !important;
}
body.light-mode.beta-ui-active .feed-item:hover {
  background: linear-gradient(180deg, #ffffff 0%, #edf1f7 100%) !important;
  border-color: #8896a7 !important;
  box-shadow: 0 3px 10px rgba(0, 0, 0, 0.07) !important;
}
body.light-mode.beta-ui-active .feed-label { color: #1e293b !important; }
body.light-mode.beta-ui-active .feed-summary { color: #475569 !important; font-weight: 600 !important; }
body.light-mode.beta-ui-active .feed-time { color: #64748b !important; }
body.light-mode.beta-ui-active .feed-restore {
  background: #ffffff !important;
  color: #2563eb !important;
}
